import React, { useContext, useState } from "react";
import { FormContext } from "../Contexts/FormContext";
import { EventCaller, ServerEventCaller } from "../BusinessLogics/EventHandler";
import axios from "axios";

const Button = ({ eid, fieldname, cap, col, mn, ev, val, mxLen }) => {
  const {
    register,
    seteDefHldr,
    formState: { errors },
  } = useContext(FormContext);
  const {
    setValue,
    getValues,
    eDefHldr,
    stageGridRefs,
    watch,
    trigger,
    stageElements,
    cntrData,
    combodata,
    setComboData,
    setEventLoading,
    modalVisible,
    setModalVisible,
    multiSearchData,
    setMultiSearchData,
    api,
    appsettings,
    generateUUID
  } = useContext(FormContext);

  const FormContextdata = {
    getValues: getValues,
    stageGridRefs: stageGridRefs,
    stageElements: stageElements,
    cntrData: cntrData,
    combodata,
    setComboData,
    setEventLoading,
    modalVisible,
    setModalVisible,
    multiSearchData,
    setMultiSearchData,
    eDefHldr
  };
  const [formData, setFormData] = useState({});

  let webcall = axios;


  let clientevent = null;
  if (eDefHldr.stg.cev[fieldname]) {
    clientevent = eDefHldr.stg.cev[fieldname].ev.click;
  }

  const handleonClick = () => {
    if (clientevent) {
      try{

        setEventLoading(true);
        eval(clientevent);
        setEventLoading(false);
      }
      catch{
        setEventLoading(false);
      }
    }
    if (eDefHldr.stg.sev[fieldname]) {
      
      ServerEventCaller(
        eDefHldr,
        getValues(),
        eDefHldr.stg.sev[fieldname].ev.click,
        stageGridRefs,
        setValue,
        FormContextdata, seteDefHldr
      );

    }
  };

  {
    return (
      <div className={`${col} mb-3 form-check`}>
        <button
          name={fieldname}
          id={fieldname}
          type="button"
          className="form-control btn btn-primary"
          disabled={eDefHldr.stg.prp[fieldname].ro}
          onClick={handleonClick}
        >
          {cap}
        </button>
      </div>
    );
  }
};

export default Button;
